# Manifest. This command's .out, .err and .exit do not exist yet.
# Do not edit this file after it runs.
# Usage: python -I work/scripts/write_manifest_t6.py NN
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

if len(sys.argv) != 2 or not re.fullmatch(r'\d+', sys.argv[1]):
    sys.stderr.write('usage: python -I work/scripts/write_manifest_t6.py NN\n')
    sys.exit(2)
SELF = f'{int(sys.argv[1]):02d}'
SELF_EXIT = Path(f'work/out/cmd/{SELF}.exit')
SELF_CMD = Path(f'work/out/cmd/{SELF}.cmd.txt')
if SELF_EXIT.exists():
    sys.stderr.write(f'{SELF}.exit already exists\n')
    sys.exit(2)

ROOT = Path('.').resolve()
EMU = Path('om-emu/emu')
IMPORT_RE = re.compile(r'''(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]''')
USE_RE = re.compile(r'''use\('([^']+)'\)''')
RESEARCH = [
    'TASK.md',
    'brief.md',
    'review-brief.md',
    'templates/result.md',
    'inputs/00_0100_50000020.decoded.bin',
    'inputs/02_0106_458c0020.decoded.bin',
    'ref/tasks/T5-afon-button-handoff/brief.md',
    'ref/tasks/T5-afon-button-handoff/decision.md',
    'ref/tasks/T7-orientation-producer/decision.md',
    'ref/tasks/T7-orientation-producer/run-20261119-072701/work/scripts/pose.mjs',
    'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes-c1.csv',
    'ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs',
    'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/design.md',
    'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/target-bytes.md',
    'ref/AF-DETECT-OFF-PROOF.md',
]


def rel(path):
    s = str(path).replace('\\', '/')
    root = str(ROOT).replace('\\', '/')
    if s.lower().startswith(root.lower() + '/'):
        s = s[len(root) + 1:]
    return s


def sha_file(path):
    data = Path(path).read_bytes()
    return hashlib.sha256(data).hexdigest(), len(data)


def tool(args):
    try:
        return subprocess.check_output(args, text=True, stderr=subprocess.STDOUT).strip()
    except Exception as e:
        return str(e)


def add_exec(store, path, digest, nbytes, where):
    key = rel(path)
    row = store.setdefault(key, {'sha256': digest, 'bytes': nbytes, 'where': []})
    if row['sha256'] != digest or (nbytes is not None and row['bytes'] not in (None, nbytes)):
        row.setdefault('conflicts', []).append({'sha256': digest, 'bytes': nbytes, 'where': where})
    elif row['bytes'] is None and nbytes is not None:
        row['bytes'] = nbytes
    row['where'].append(where)


def resolve_spec(from_file, spec):
    if spec.startswith('node:') or spec.startswith('node_modules'):
        return None
    base = Path(from_file).parent / spec if spec.startswith('.') else EMU / spec
    for candidate in (base, Path(str(base) + '.mjs'), Path(str(base) + '.js'), base / 'index.mjs', base / 'index.js'):
        if candidate.is_file():
            return candidate
    return None


def walk_imports(starts):
    found = []
    seen = set()
    queue = [Path(p) for p in starts]
    while queue:
        path = queue.pop()
        key = rel(path)
        if key in seen or not path.is_file():
            continue
        seen.add(key)
        if key.startswith('work/scripts/'):
            pass
        else:
            found.append(path)
        text = path.read_text(encoding='utf-8', errors='replace')
        specs = IMPORT_RE.findall(text) + USE_RE.findall(text)
        for spec in specs:
            nxt = resolve_spec(path, spec)
            if nxt is not None:
                queue.append(nxt)
    return found


exec_hashes = {}
for path in sorted(Path('work/out').rglob('*.jsonl')):
    text = path.read_text(encoding='utf-8', errors='replace')
    if '"helper-hashes"' not in text:
        continue
    for line in text.splitlines():
        if '"helper-hashes"' not in line:
            continue
        rec = json.loads(line)
        if rec.get('step') != 'helper-hashes':
            continue
        where = rel(path) + '#helper-hashes'
        for item in rec.get('helpers', []) + rec.get('resources', []):
            add_exec(exec_hashes, item['path'], item['sha256'], item.get('bytes'), where)

for exit_path in sorted(Path('work/out/cmd').glob('*.exit'), key=lambda p: int(p.name.split('.')[0])):
    doc = json.loads(exit_path.read_text(encoding='utf-8'))
    for item in doc.get('scripts') or []:
        add_exec(exec_hashes, item['path'], item['sha256'], item.get('bytes'), rel(exit_path))

for cmd_path in sorted(Path('work/out/cmd').glob('*.cmd.txt')):
    text = cmd_path.read_text(encoding='utf-8')
    wrap = re.search(r'wrapper_sha256: ([0-9a-f]+)', text)
    if wrap:
        add_exec(exec_hashes, 'work/scripts/run_logged.mjs', wrap.group(1), None, rel(cmd_path))
if SELF_CMD.is_file():
    cmd_text = SELF_CMD.read_text(encoding='utf-8')
    blocks = re.findall(r'script: (.+)\nscript_sha256: ([0-9a-f]+)\nscript_bytes: (\d+)', cmd_text)
    for path, digest, nbytes in blocks:
        if path != 'none':
            add_exec(exec_hashes, path, digest, int(nbytes), rel(SELF_CMD))

inputs = []
seen = set()
for key, rec in sorted(exec_hashes.items()):
    if key.startswith('work/'):
        continue
    file_path = Path(key)
    if not file_path.is_file():
        inputs.append({
            'path': key, 'sha256': rec['sha256'], 'bytes': rec['bytes'], 'hashed': 'execution',
            'execution_where': rec['where'], 'later_matches': None, 'note': 'path is not a file',
        })
        seen.add(key)
        continue
    later, nbytes = sha_file(file_path)
    inputs.append({
        'path': key, 'sha256': rec['sha256'], 'bytes': rec['bytes'], 'hashed': 'execution',
        'execution_where': rec['where'], 'later_sha256': later,
        'later_matches': later == rec['sha256'] and (rec['bytes'] is None or nbytes == rec['bytes']),
        'conflicts': rec.get('conflicts', []),
    })
    seen.add(key)

starts = [
    'ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs',
    'ref/tasks/T7-orientation-producer/run-20261119-072701/work/scripts/pose.mjs',
]
starts.extend(str(p).replace('\\', '/') for p in Path('work/scripts').glob('*.mjs'))
for path in walk_imports(starts):
    key = rel(path)
    if key in seen or key.startswith('work/'):
        continue
    digest, nbytes = sha_file(path)
    inputs.append({'path': key, 'sha256': digest, 'bytes': nbytes, 'hashed': 'later', 'note': 'imported module, hashed when the manifest was written'})
    seen.add(key)

for path in RESEARCH:
    if rel(path) in seen:
        continue
    if not Path(path).is_file():
        sys.stderr.write('missing ' + path + '\n')
        sys.exit(2)
    digest, nbytes = sha_file(path)
    inputs.append({'path': rel(path), 'sha256': digest, 'bytes': nbytes, 'hashed': 'later'})
    seen.add(rel(path))

sources = []
for path in sorted(Path('work/scripts').glob('*')):
    if not path.is_file():
        continue
    digest, nbytes = sha_file(path)
    key = rel(path)
    row = {'path': key, 'sha256': digest, 'bytes': nbytes, 'hashed': 'later'}
    if key in exec_hashes:
        rec = exec_hashes[key]
        row['hashed'] = 'execution'
        row['execution_sha256'] = rec['sha256']
        row['execution_where'] = rec['where']
        row['later_matches'] = digest == rec['sha256'] and (rec['bytes'] is None or nbytes == rec['bytes'])
        row['conflicts'] = rec.get('conflicts', [])
    sources.append(row)

supplement = {
    'command': SELF,
    'note': (
        f'work/out/cmd/{SELF}.out, work/out/cmd/{SELF}.err and work/out/cmd/{SELF}.exit '
        'are written by the wrapper after the manifest closes. They are not hashed.'
    ),
}
if SELF_CMD.is_file():
    digest, nbytes = sha_file(SELF_CMD)
    supplement['cmd_txt'] = {'path': rel(SELF_CMD), 'sha256': digest, 'bytes': nbytes}
Path('work/out/manifest-supplement-t6.json').write_text(json.dumps(supplement, indent=2) + '\n', encoding='utf-8')

outputs = []
out_files = [Path('work/result.md')]
out_files.extend(p for p in Path('work/out').rglob('*') if p.is_file())
for path in sorted(out_files, key=lambda p: rel(p)):
    digest, nbytes = sha_file(path)
    outputs.append({'path': rel(path), 'sha256': digest, 'bytes': nbytes, 'hashed': 'later'})

commands = []
present = []
for exit_path in sorted(Path('work/out/cmd').glob('*.exit'), key=lambda p: int(p.name.split('.')[0])):
    doc = json.loads(exit_path.read_text(encoding='utf-8'))
    n = exit_path.name.split('.')[0]
    present.append(n)
    row = {
        'id': n, 'spawn': doc.get('spawn'), 'status': doc.get('status'),
        'start': doc.get('start'), 'end': doc.get('end'), 'hashed': 'later',
    }
    for suffix, key in (('cmd.txt', 'cmd_file'), ('out', 'out_file'), ('err', 'err_file'), ('exit', 'exit_file')):
        file_path = Path(f'work/out/cmd/{n}.{suffix}')
        if file_path.is_file():
            row[key] = rel(file_path)
    commands.append(row)
missing = [f'{i:02d}' for i in range(1, int(SELF)) if f'{i:02d}' not in present]
self_row = {
    'id': SELF,
    'spawn': f'python -I work/scripts/write_manifest_t6.py {int(SELF)}',
    'status': None,
    'hashed': 'later',
    'note': supplement['note'],
}
if SELF_CMD.is_file():
    self_row['cmd_file'] = rel(SELF_CMD)
commands.append(self_row)

brief_sha, _ = sha_file('brief.md')
manifest = {
    'task': 'T6',
    'brief_sha256': brief_sha,
    'brief_hashed': 'later',
    'inputs': inputs,
    'sources': sources,
    'outputs': outputs,
    'commands': commands,
    'tool_versions': {
        'node26': tool(['cmd.exe', '/d', '/c', 'node26 --version']),
        'python': tool(['python', '--version']),
    },
    'note': (
        'EMULATOR-ONLY. No firmware image was written. om-emu was not modified. '
        'pose.mjs was imported and not edited. The profile mirror stays in RAM. '
        'Subject Detect stayed 0. The three section-7 bytes are the inherited call site. '
        f'Command {SELF} .out, .err and .exit are sealed only by the supplement note: '
        'the wrapper creates them after this file closes. The manifest file is not an output entry.'
    ),
}
if missing:
    manifest['missing_commands'] = missing
Path('work/evidence-manifest.json').write_text(json.dumps(manifest, indent=2) + '\n', encoding='utf-8')
bad = [row['path'] for row in inputs + sources if row.get('later_matches') is False or row.get('conflicts')]
print('inputs', len(inputs), 'sources', len(sources), 'outputs', len(outputs), 'commands', len(commands))
print('missing', missing)
print('mismatches', bad)
if bad or missing:
    sys.exit(1)
